  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Clobazam, a 7-chloro 1,5-benzodiazepine, has 90% oral bioavailability in fasted healthy volunteers, supporting high F for the structurally related 7-chloro benzodiazepine query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Estazolam, a 7-chloro-5-phenyl benzodiazepine, has 87% oral bioavailability in healthy volunteers, directly supporting high F for the query's core benzodiazepine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Alprazolam, a 7-chloro-5-phenyl triazolobenzodiazepine, has oral bioavailability of 80-100% in humans, indicating minimal presystemic extraction for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Diazepam, a 7-chloro-1,4-benzodiazepine, has absolute oral bioavailability not significantly different from 100% in human volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Triazolam, a close triazolobenzodiazepine analogue, has mean oral bioavailability of about 55% (range 22-116%), still well above the 20% threshold and supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Adinazolam, a triazolobenzodiazepine with a basic dimethylaminomethyl substituent, has absolute oral bioavailability of about 39%, still above 20% and supporting high F despite added polar/basic functionality.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a 7-chloro-5-phenyl-1,4-benzodiazepine N-oxide (chlordiazepoxide-like). Multiple close benzodiazepine analogues with the same chlorophenyl diazepine core show oral bioavailability values of 39-100%, all above the 20% threshold. The most direct analogues (clobazam 90%, estazolam 87%, alprazolam 80-100%, diazepam ~100%) strongly support high F. Even analogues with lower F due to first-pass metabolism (triazolam ~55%, adinazolam ~40%) remain well above 20%. The physicochemical prior is also favorable. Therefore predict high.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the exact query molecule (chlordiazepoxide) was provided; prediction relies on close benzodiazepine analogues.",
    "The metabolic fate of the N-oxide and amidine groups in the query is not directly measured in the evidence, though it does not appear to threaten the F>=20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

